-- 389: Original BrillaPrep NSMQ subj_nsmq_math speed_race beta questions (batch 001).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_389_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_389_guard;
INSERT INTO _migration_389_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_sr_b001_001' AND NOT (q.topic_id IS 'topic_algebra' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Evaluate log base 10 of 1000.' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS '3' AND q.explanation IS 'Since 1000 = 10³, log₁₀ 1000 = 3 by the definition of a logarithm as the power to which the base must be raised.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_sr_b001_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_389_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_sr_b001_002' AND NOT (q.topic_id IS 'topic_calculus' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the derivative of x³ with respect to x?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS '3x²' AND q.explanation IS 'By the power rule d/dx(xⁿ) = nxⁿ⁻¹ with n = 3, the derivative is 3x². This gives the gradient of the cubic curve at any point x.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_sr_b001_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_389_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_sr_b001_003' AND NOT (q.topic_id IS 'topic_trigonometry' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the exact value of cos 60°?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS '1/2' AND q.explanation IS 'From the standard 30-60-90 triangle, cos 60° = adjacent/hypotenuse = 1/2. It is one of the exact trigonometric values expected to be recalled instantly.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_sr_b001_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_389_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_sr_b001_004' AND NOT (q.topic_id IS 'topic_statistics' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the next term of the sequence 2, 5, 8, 11, …?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS '14' AND q.explanation IS 'Each term increases by a common difference of 3, so the sequence is arithmetic. The next term is 11 + 3 = 14.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_sr_b001_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
